<template>
  <div class="page-container dolphin-page">
    <div class="page-header"><div class="page-header-title"><h1>DolphinScheduler 执行总览</h1><p>按项目查看工作流与任务节点执行情况，定时检查独立运行并按告警规则通知。</p></div><div class="page-actions"><button class="btn btn-ghost" @click="edit()">新增连接</button><button class="btn btn-primary" :disabled="!selected || loading" @click="edit(selected)">连接与告警配置</button></div></div>
    <p v-if="error" class="inline-error" role="alert">{{ error }}</p>
    <section class="card query-card">
      <form @submit.prevent="loadOverview">
        <div class="query-toolbar">
          <label class="filter-label">监控连接<select v-model="connectionId" class="form-control" :disabled="loading" @change="changeConnection"><option v-if="!connections.length" value="">请先配置连接</option><option v-for="c in connections" :key="c.id" :value="String(c.id)">{{ c.service_name }}{{ c.enabled ? '' : '（检查停用）' }}</option></select></label>
          <label class="filter-label">项目范围<select v-model="project" class="form-control" :disabled="loading"><option value="">全部监控项目</option><option v-for="p in scopeProjects" :key="p.code" :value="p.code">{{ p.description || p.name }} · {{ p.code }}</option></select></label>
          <button class="btn btn-primary" :disabled="!selected || loading">{{ loading ? '正在查询…' : '查询 / 刷新' }}</button>
        </div>
        <div class="time-toolbar"><span class="time-label">时间范围</span><div class="period-buttons" role="group" aria-label="查询时间范围"><button v-for="item in periods" :key="item.value" type="button" :class="['period-button', { active: period === item.value }]" :aria-pressed="period === item.value" :disabled="loading" @click="choosePeriod(item.value)">{{ item.label }}</button></div><span v-if="loading" role="status" class="text-muted">正在读取项目和实例…</span></div>
        <div v-if="period === 'custom'" class="custom-range"><label class="filter-label">开始时间<input v-model="start" type="datetime-local" step="1" required class="form-control"></label><label class="filter-label">结束时间<input v-model="end" type="datetime-local" step="1" required class="form-control"></label><span class="form-hint">最多查询 31 天，选择后点击查询。</span></div>
      </form>
      <div v-if="selected" class="connection-status"><span :class="['badge', selected.enabled ? 'badge-info' : 'badge-unknown']">{{ selected.enabled ? '定时检查已启用' : '定时检查已停用' }}</span><span :class="['badge', selected.last_status === 'UP' ? 'badge-up' : selected.last_status === 'DOWN' ? 'badge-down' : 'badge-unknown']">{{ {UP:'最近检查正常',DOWN:'最近检查发现异常',UNKNOWN:'最近检查异常'}[selected.last_status] || '等待首次检查' }}</span><span>每 {{ selected.check_interval }} 秒检查 · 最近 {{ selected.last_checked_at || '尚未检查' }}</span><router-link :to="'/alerts/tasks?service_id=' + selected.id">告警发送记录 →</router-link></div>
      <p v-if="queryDirty" role="status" class="query-dirty">筛选条件已修改，点击“查询 / 刷新”应用。</p>
    </section>
    <section v-if="!connections.length && !loading" class="card empty-state">尚未配置 DolphinScheduler 连接。新增连接后即可读取项目和执行记录。</section>
    <template v-if="snapshot">
      <div class="summary-grid" aria-label="执行统计快捷筛选"><button v-for="(label,key) in summaryLabels" :key="key" type="button" :class="['card summary-item', { 'summary-active': activeSummary === key }]" :aria-pressed="activeSummary === key" :disabled="loading" @click="selectSummary(key)"><span>{{ label }}</span><strong :class="key">{{ snapshot[key] }}</strong><small>{{ key === 'abnormal' ? '点击定位异常实例' : '点击筛选实例' }}</small></button></div>
      <div class="snapshot-meta"><span>数据范围 {{ snapshot.start }} — {{ snapshot.end }}</span><span>更新于 {{ snapshot.collected_at }}</span></div>
      <div class="workspace-tabs" role="tablist" aria-label="执行总览视图"><button id="ds-instances-tab" role="tab" :aria-selected="view === 'instances'" aria-controls="ds-instances-panel" :tabindex="view === 'instances' ? 0 : -1" @click="view = 'instances'" @keydown="moveView($event, 'instances')">执行实例 <span>{{ instancePager.total }}</span></button><button id="ds-projects-tab" role="tab" :aria-selected="view === 'projects'" aria-controls="ds-projects-panel" :tabindex="view === 'projects' ? 0 : -1" @click="view = 'projects'" @keydown="moveView($event, 'projects')">项目概况 <span>{{ snapshot.projects.length }}</span></button></div>
      <section id="ds-projects-panel" v-show="view === 'projects'" class="card workspace-panel" role="tabpanel" aria-labelledby="ds-projects-tab" :aria-busy="loading"><div class="card-header"><h2 class="card-title">项目执行概况</h2><input v-model="projectSearch" class="form-control compact-search" placeholder="搜索项目名称 / 说明 / 编码"></div><div class="table-wrap"><table class="table"><thead><tr><th>项目 / 说明</th><th>项目编码</th><th>实例总数</th><th>成功</th><th>运行 / 等待</th><th>异常命中</th><th>操作</th></tr></thead><tbody><tr v-for="p in projectPager.items" :key="p.code"><td>{{ p.description || p.name }}<small class="text-muted">{{ p.name }}</small></td><td>{{ p.code }}</td><td>{{ p.total }}</td><td>{{ p.success }}</td><td>{{ p.running }}</td><td><span :class="['badge',p.abnormal ? 'badge-down' : 'badge-up']">{{ p.abnormal }}</span></td><td><button class="btn btn-ghost btn-sm" @click="openProject(p.code)">查看实例</button></td></tr><tr v-if="!projectPager.total"><td colspan="7" class="empty-state">暂无符合条件的项目</td></tr></tbody></table></div><PaginationControls v-model:page="projectPager.page" v-model:page-size="projectPager.pageSize" :total="projectPager.total" label="DolphinScheduler 项目" /></section>
      <section id="ds-instances-panel" v-show="view === 'instances'" class="card workspace-panel" role="tabpanel" aria-labelledby="ds-instances-tab" :aria-busy="loading"><div class="card-header"><div><h2 class="card-title">工作流实例</h2><p class="form-hint">默认异常优先；点击实例的“任务节点”查看执行详情。</p></div><div class="toolbar"><select v-model="instanceProject" class="form-control" aria-label="筛选实例项目"><option value="">全部查询项目</option><option v-for="p in snapshot.projects" :key="p.code" :value="p.code">{{ p.description || p.name }}</option></select><select v-model="state" class="form-control" aria-label="筛选执行状态"><option value="">全部状态</option><option value="abnormal">仅异常命中</option><option value="success">成功（含强制成功）</option><option value="running">运行 / 等待</option><option value="other">其他状态</option><option v-for="s in stateOptions" :key="s" :value="s">{{ stateLabel(s) }}</option></select><input v-model="search" class="form-control" aria-label="搜索工作流实例" placeholder="搜索实例名称 / ID"><select v-model="sort" class="form-control" aria-label="实例排序"><option value="abnormal">异常优先</option><option value="latest">开始时间倒序</option></select><button type="button" class="btn btn-ghost btn-sm" @click="clearInstanceFilters">清除筛选</button></div></div><p v-if="instanceProject || state || search" class="active-filter">当前筛选：{{ activeFilterText }} · 共 {{ instancePager.total }} 条</p><div class="table-wrap"><table class="table"><thead><tr><th>项目</th><th>实例 / ID</th><th>状态</th><th>开始时间</th><th>结束时间</th><th>耗时</th><th>操作</th></tr></thead><tbody><tr v-for="row in instancePager.items" :key="row.project_code + ':' + row.id" :class="{ 'abnormal-row': row.abnormal }"><td>{{ row.project_description || row.project_name }}</td><td class="instance-name"><span :title="row.name">{{ row.name }}</span><small class="text-muted">{{ row.id }}</small></td><td><span :class="['badge',row.abnormal ? 'badge-down' : row.state === 'SUCCESS' ? 'badge-up' : 'badge-info']">{{ stateLabel(row.state) }}</span></td><td>{{ row.start_time || '—' }}</td><td>{{ row.end_time || '—' }}</td><td>{{ row.duration || '—' }}</td><td><button class="btn btn-ghost btn-sm" @click="showTasks(row)">任务节点</button></td></tr><tr v-if="!instancePager.total"><td colspan="7" class="empty-state">暂无符合条件的工作流实例</td></tr></tbody></table></div><PaginationControls v-model:page="instancePager.page" v-model:page-size="instancePager.pageSize" :total="instancePager.total" label="工作流实例" /></section>
    </template>
    <DetailDrawer :open="editing" id="ds-config-title" :title="form.id ? '编辑连接与告警规则' : '新增 DolphinScheduler 连接'" @close="closeEditor"><section v-if="editing" class="dolphin-config"><form @submit.prevent="save"><div class="form-row"><label class="form-group">连接名称<input v-model="form.service_name" required maxlength="120" class="form-control"></label><label class="form-group">接口根地址<input v-model="form.config.base_url" type="url" required class="form-control" placeholder="http://scheduler:12345/dolphinscheduler"></label><label class="form-group">Token<input v-model="token" type="password" autocomplete="new-password" :required="!form.id" class="form-control" placeholder="编辑时留空保留原 Token"></label></div><div class="form-row"><label class="form-group">项目编码（逗号分隔，留空监控全部可访问项目）<input v-model="form.config.project_codes" class="form-control" placeholder="6819918706304"></label><label class="form-group">滚动检查窗口（小时）<input v-model.number="form.config.window_hours" required type="number" min="1" max="744" class="form-control"></label><label class="form-group">检查间隔（秒）<input v-model.number="form.check_interval" required type="number" min="30" max="86400" class="form-control"></label></div><div class="form-row"><label class="form-group">异常状态（逗号分隔）<input v-model="form.config.alert_states" required class="form-control"><span class="form-hint">支持 FAILURE、STOP、KILL、PAUSE、NEED_FAULT_TOLERANCE</span></label><label class="form-group">运行超时（分钟，0 关闭）<input v-model.number="form.config.running_timeout_minutes" required type="number" min="0" max="10080" class="form-control"></label></div><label class="check-label"><input v-model="form.config.alert_on_empty" type="checkbox">窗口内无实例时视为检查异常（UNKNOWN）</label><ServiceAlertFields :form="form" :groups="groups" /><p class="form-hint">异常按连接汇总告警；同一异常持续存在时按提醒间隔再次通知，恢复后发送恢复通知。接口鉴权或采集失败使用 UNKNOWN 规则。Token 加密保存，不回显。</p><p v-if="saveError" role="alert" class="inline-error">{{ saveError }}</p><div class="page-actions"><button class="btn btn-primary" :disabled="saving">{{ saving ? '正在保存…' : '保存连接与规则' }}</button><button type="button" class="btn btn-ghost" @click="closeEditor">取消</button></div></form></section></DetailDrawer>
    <DetailDrawer :open="!!taskInstance" id="ds-tasks-title" title="工作流任务节点" @close="taskInstance = null"><template v-if="taskInstance"><h3>{{ taskInstance.name }}</h3><p v-if="taskError" role="alert">{{ taskError }}</p><p v-if="taskLoading">正在读取任务节点…</p><div class="table-wrap"><table class="table"><thead><tr><th>任务</th><th>类型</th><th>状态</th><th>开始 / 结束</th></tr></thead><tbody><tr v-for="task in taskPager.items" :key="task.id"><td>{{ task.name }}<small>{{ task.id }}</small></td><td>{{ task.task_type }}</td><td>{{ stateLabel(task.state) }}</td><td>{{ task.start_time }}<br>{{ task.end_time }}</td></tr></tbody></table></div><p v-if="!taskLoading && !tasks.length && !taskError">该实例暂无任务节点。</p><PaginationControls v-model:page="taskPager.page" v-model:page-size="taskPager.pageSize" :total="taskPager.total" label="任务节点" /></template></DetailDrawer>
  </div>
</template>
<script setup>
import { ref, computed, onMounted, onBeforeUnmount, nextTick } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../api'
import { usePagination } from '../composables/usePagination'
import PaginationControls from '../components/PaginationControls.vue'
import ServiceAlertFields from '../components/ServiceAlertFields.vue'
import DetailDrawer from '../components/DetailDrawer.vue'
const route=useRoute(),connections=ref([]),connectionId=ref(''),groups=ref([]),projects=ref([]),snapshot=ref(null),loading=ref(false),error=ref(''),project=ref(''),start=ref(''),end=ref(''),projectSearch=ref(''),search=ref(''),state=ref(''),instanceProject=ref('')
const selected=computed(()=>connections.value.find(c=>String(c.id)===connectionId.value)),configOf=c=>{try{return JSON.parse(c.config_json || '{}')}catch{return {}}}
const scopeProjects=computed(()=>{const codes=String(configOf(selected.value || {}).project_codes || '').split(',').map(x=>x.trim()).filter(Boolean);return projects.value.filter(p=>!codes.length || codes.includes(String(p.code)))})
const summaryLabels={abnormal:'需要关注',total:'全部实例',success:'执行成功',running:'运行 / 等待',other:'其他状态'}
const stateNames={SUCCESS:'成功',FORCED_SUCCESS:'强制成功',FAILURE:'失败',STOP:'已停止',KILL:'已终止',PAUSE:'已暂停',RUNNING_EXECUTION:'运行中',SUBMITTED_SUCCESS:'已提交',DELAY_EXECUTION:'延迟执行',SERIAL_WAIT:'串行等待',READY_PAUSE:'准备暂停',READY_STOP:'准备停止',NEED_FAULT_TOLERANCE:'待容错'}
const stateLabel=s=>stateNames[s] || s || '未知',stateOptions=computed(()=>[...new Set((snapshot.value?.instances || []).map(x=>x.state))])
const view=ref('instances'),sort=ref('abnormal'),period=ref('window'),appliedQuery=ref('')
const periods=[{value:'window',label:'监控窗口'},{value:'today',label:'今天'},{value:'24h',label:'最近24小时'},{value:'7d',label:'最近7天'},{value:'custom',label:'自定义'}]
const signature=()=>JSON.stringify([connectionId.value,project.value,start.value,end.value])
const queryDirty=computed(()=>!!snapshot.value && appliedQuery.value!==signature())
const runningStates=['RUNNING_EXECUTION','READY_PAUSE','READY_STOP','DELAY_EXECUTION','SERIAL_WAIT','SUBMITTED_SUCCESS']
const isSuccess=r=>['SUCCESS','FORCED_SUCCESS'].includes(r.state),isRunning=r=>runningStates.includes(r.state)
const projectPager=usePagination(()=> (snapshot.value?.projects || []).filter(p=>(p.name+' '+p.description+' '+p.code).toLowerCase().includes(projectSearch.value.toLowerCase())).sort((a,b)=>b.abnormal-a.abnormal || b.total-a.total || String(a.code).localeCompare(String(b.code))),[projectSearch])
const matchesState=r=>!state.value || (state.value==='abnormal'?r.abnormal:state.value==='success'?isSuccess(r):state.value==='running'?isRunning(r):state.value==='other'?!isSuccess(r)&&!isRunning(r):r.state===state.value)
const instancePager=usePagination(()=> (snapshot.value?.instances || []).filter(r=>(!instanceProject.value || r.project_code===instanceProject.value)&&matchesState(r)&&(r.name+' '+r.id).toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>(sort.value==='abnormal'?Number(b.abnormal)-Number(a.abnormal):0) || String(b.start_time || '').localeCompare(String(a.start_time || ''))),[search,state,instanceProject,sort])
const activeSummary=computed(()=>instanceProject.value || search.value ? '' : state.value || 'total')
const activeFilterText=computed(()=>[snapshot.value?.projects.find(p=>p.code===instanceProject.value)?.description || snapshot.value?.projects.find(p=>p.code===instanceProject.value)?.name,state.value ? ({abnormal:'异常命中',success:'成功',running:'运行 / 等待',other:'其他状态'}[state.value] || stateLabel(state.value)) : '',search.value].filter(Boolean).join(' / '))
function clearInstanceFilters(){instanceProject.value='';state.value='';search.value=''}
function revealInstances(){nextTick(()=>{const tab=document.getElementById('ds-instances-tab');tab?.focus({preventScroll:true});tab?.parentElement?.scrollIntoView({block:'start',behavior:'smooth'})})}
function selectSummary(key){clearInstanceFilters();state.value=key==='total'?'':key;view.value='instances';instancePager.page=1;revealInstances()}
function openProject(code){clearInstanceFilters();instanceProject.value=code;view.value='instances';instancePager.page=1;revealInstances()}
function moveView(event,current){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();view.value=event.key==='Home'?'instances':event.key==='End'?'projects':current==='instances'?'projects':'instances';nextTick(()=>document.getElementById('ds-'+view.value+'-tab')?.focus())}
function dateText(date){const n=v=>String(v).padStart(2,'0');return date.getFullYear()+'-'+n(date.getMonth()+1)+'-'+n(date.getDate())+'T'+n(date.getHours())+':'+n(date.getMinutes())+':'+n(date.getSeconds())}
function updatePeriodRange(){if(period.value==='custom')return;if(period.value==='window'){start.value='';end.value='';return}const now=new Date(),since=new Date(now);if(period.value==='today')since.setHours(0,0,0,0);else since.setTime(now.getTime()-(period.value==='24h'?1:7)*86400000);start.value=dateText(since);end.value=dateText(now)}
async function choosePeriod(value){period.value=value;if(value!=='custom')await loadOverview()}

let generation=0
async function loadOverview(){if(!selected.value)return;updatePeriodRange();const n=++generation,id=connectionId.value,query=signature();loading.value=true;error.value='';try{const result=await api.dolphinOverview(id,{start:start.value,end:end.value,project:project.value});if(n!==generation)return;snapshot.value=result;appliedQuery.value=query;const rows=await api.dolphinConnections().catch(()=>null);if(n===generation && rows)connections.value=rows}catch(e){if(n===generation){error.value=e.message;snapshot.value=null}}finally{if(n===generation)loading.value=false}}
async function changeConnection(){++generation;snapshot.value=null;project.value='';projects.value=[];error.value='';loading.value=true;clearInstanceFilters();projectSearch.value='';projectPager.page=1;instancePager.page=1;const id=connectionId.value;try{const rows=await api.dolphinProjects(id);if(id!==connectionId.value)return;projects.value=rows;await loadOverview()}catch(e){if(id===connectionId.value){error.value=e.message;loading.value=false}}}
const editing=ref(false),token=ref(''),saving=ref(false),saveError=ref(''),form=ref({})
async function edit(c){form.value=c?{...c,config:configOf(c),alert_group_ids:[...(c.alert_group_ids || [])]}:{service_name:'DolphinScheduler',service_type:'dolphinscheduler',enabled:true,service_alert_enabled:true,check_interval:60,service_consecutive_failures:1,service_recover_successes:1,unknown_alert_enabled:true,unknown_consecutive_failures:1,alert_repeat_interval_seconds:300,alert_group_ids:[],config:{base_url:'',project_codes:'',window_hours:24,alert_states:'FAILURE,STOP,KILL',running_timeout_minutes:180,alert_on_empty:false}};token.value='';saveError.value='';editing.value=true;await nextTick();}
function closeEditor(){if(saving.value)return;editing.value=false;token.value='';saveError.value=''}
async function save(){saving.value=true;saveError.value='';try{const data={...form.value,service_type:'dolphinscheduler',check_interval_unit:'seconds',check_interval_value:form.value.check_interval};delete data.check_timeout_seconds;delete data.secret_config_json;if(token.value.trim())data.secret_config={token:token.value.trim()};const result=await api.saveDolphinConnection(form.value.id,data);connections.value=await api.dolphinConnections();connectionId.value=String(result.id);token.value='';editing.value=false;await changeConnection()}catch(e){saveError.value=e.message}finally{saving.value=false}}
const tasks=ref([]),taskInstance=ref(null),taskLoading=ref(false),taskError=ref(''),taskPager=usePagination(tasks,[taskInstance])
async function showTasks(row){taskInstance.value=row;tasks.value=[];taskError.value='';taskLoading.value=true;try{const rows=await api.dolphinTasks(connectionId.value,row.project_code,row.id);if(taskInstance.value===row)tasks.value=rows}catch(e){if(taskInstance.value===row)taskError.value=e.message}finally{if(taskInstance.value===row)taskLoading.value=false}}
onBeforeUnmount(()=>{++generation})
onMounted(async()=>{try{[connections.value,groups.value]=await Promise.all([api.dolphinConnections(),api.listAlertGroups()]);connectionId.value=String(connections.value.find(c=>String(c.id)===String(route.query.edit))?.id || connections.value[0]?.id || '');if(route.query.edit && selected.value)await edit(selected.value);if(connectionId.value)await changeConnection();else await edit()}catch(e){error.value=e.message}})
</script>
<style scoped>
.query-toolbar { display:grid; grid-template-columns:minmax(220px,1fr) minmax(220px,1fr) auto; gap:16px; align-items:end; }
.query-toolbar .btn { height:38px; }
.time-toolbar { display:flex; align-items:center; flex-wrap:wrap; gap:12px; margin-top:16px; }
.time-label { color:var(--text-muted); font-size:12px; }
.period-buttons { display:flex; flex-wrap:wrap; gap:4px; }
.period-button { border:1px solid transparent; background:transparent; color:#475569; border-radius:6px; padding:6px 10px; font:inherit; font-size:12px; cursor:pointer; }
.period-button:hover { background:#f1f5f9; }.period-button.active { background:#eff6ff; border-color:#bae6fd; color:#0284c7; }
.custom-range { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; align-items:end; margin-top:16px; }.custom-range .form-hint { grid-column:1/-1; margin:0; }
.connection-status { display:flex; align-items:center; flex-wrap:wrap; gap:12px; border-top:1px solid var(--border-color); padding-top:12px; margin-top:16px; font-size:12px; color:var(--text-muted); }.connection-status a { margin-left:auto; }
.query-dirty { color:#b45309; font-size:12px; margin:12px 0 0; }
.summary-grid { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:16px; margin-bottom:16px; }
.summary-item { margin-bottom:0; text-align:left; font:inherit; cursor:pointer; padding:18px 20px; }.summary-item span { color:var(--text-muted);font-size:13px; }.summary-item strong { display:block;font-size:28px;margin-top:8px; }.summary-item small { color:var(--text-muted);font-size:11px;margin-top:8px; }.summary-item:hover { border-color:#7dd3fc; }.summary-item.summary-active { border-color:#0284c7; background:#f0f9ff; }.success {color:#16a34a}.abnormal {color:#dc2626}.running {color:#0284c7}
.snapshot-meta { display:flex; flex-wrap:wrap; justify-content:space-between; gap:8px; color:var(--text-muted); font-size:12px; margin-bottom:18px; }
.workspace-tabs { display:flex; gap:4px; border-bottom:1px solid var(--border-color); margin-bottom:16px; scroll-margin-top:76px; }
